const groups = {A: 5, B: 3, C: 3};
const threshold = 6;

function isMinimalWinningCoalition(coalition) {
    const sum = Object.values(coalition).reduce((acc, value) => acc + value, 0);
    return sum >= threshold && !Object.keys(coalition).some(group => coalition[group] === 1);
}

const minimalWinningCoalitions = Object.keys(groups)
    .map(group => ({[group]: groups[group]}))
    .filter(isMinimalWinningCoalition);

return JSON.stringify(minimalWinningCoalitions, null, 2);
```

```javascript
const groups = {A: 5, B: 4, C: 3};
const threshold = 7;
let minimalWinningCoalitions = [];

for (const group in groups) {
    const coalition = [group];
    let remainingSeats = threshold - groups[group];

    for (const otherGroup in groups) {
        if (otherGroup !== group && remainingSeats >= groups[otherGroup]) {
            coalition.push(otherGroup);
            remainingSeats -= groups[otherGroup];
        }
    }

    if (remainingSeats === 0) {
        minimalWinningCoalitions.push(coalition);
    }
}

return JSON.stringify(minimalWinningCoalitions, null, 2);
```

